def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Find each connected 3-shaped region and its bounding box.
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == 3 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            boxes.append((min(x for x, y in cells), max(x for x, y in cells),
                          min(y for x, y in cells), max(y for x, y in cells)))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if any(rmin <= r <= rmax and cmin <= c <= cmax
                   for rmin, rmax, cmin, cmax in boxes):
                for rr in range(max(0, r - 1), min(h, r + 2)):
                    for cc in range(max(0, c - 1), min(w, c + 2)):
                        if grid[rr][cc] == 3:
                            out[rr][cc] = 1
                        elif grid[rr][cc] == 0:
                            out[rr][cc] = 1
    return out
